from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1];folder=root/'release'
items=[('IA · tipografía y compositor horizontal','chat','qa-charvis-624-welcome-1440.png'),('Inicio','general','qa-624-inicio.png'),('Estudio','general','qa-624-estudio.png'),('Tareas','general','qa-624-tareas.png'),('Notas','general','qa-624-notas.png'),('Música','general','qa-624-musica.png'),('Planificador','general','qa-624-planificacion.png'),('Cursos','general','qa-624-cursos.png'),('Interior de curso','general','qa-624-curso_detalle.png'),('IA · inicio','chat','qa-624-ia.png'),('Ajustes','general','qa-624-ajustes.png'),('Chat · respuesta y fuentes','chat','qa-charvis-624-research.png'),('Proyecto · compositor integrado','chat','qa-charvis-624-project.png'),('Buscar conversaciones','chat','qa-charvis-624-search.png'),('Conexión · proveedores','chat','qa-charvis-624-settings.png'),('Chat · 420 px','chat','qa-charvis-624-welcome-420.png'),('Chat · 900 px','chat','qa-charvis-624-welcome-900.png'),('Artista · buscador debajo del encabezado','music','qa-music-6241-discovery-900.png'),('Reproductor · acciones horizontales sin fondo','music','qa-music-6241-widget.png'),('Artista · canciones y colaboraciones','music','qa-music-624-artist.png'),('Tarea · panel estrecho','tasks','qa-task-624-narrow.png'),('Tareas · gráficas y leyenda','tasks','qa-task-624-overview.png')]
figures=[]
for title,group,name in items:
 if (folder/name).exists(): figures.append(f'<figure data-group="{group}"><figcaption>{escape(title)}</figcaption><a href="{name}" target="_blank"><img loading="lazy" src="{name}" alt="{escape(title)}"></a></figure>')
status=json.loads((folder/'build-6.24.1.status.json').read_text(encoding='utf-8-sig'))
manifest=json.loads((folder/'apheka_FINAL.json').read_text(encoding='utf-8-sig'))
ready=status.get('state')=='complete' and manifest.get('version')=='6.24.1'
installer='Instalador compilado y verificado.' if ready else 'Instalador en empaquetado.'
download='<p><a href="apheka_FINAL.exe">Descargar instalador APHEKA 6.24.1</a></p>' if ready else ''
html='''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APHEKA 6.24.1 · Capturas</title><style>*{box-sizing:border-box}body{margin:0;background:#111314;color:#eaedea;font:15px/1.65 system-ui,sans-serif}main{max-width:1560px;margin:auto;padding:36px 26px}header{border-bottom:1px solid #363a3a;padding-bottom:22px;margin-bottom:22px}h1{font-size:30px;letter-spacing:-.04em;font-weight:550;margin:4px 0 12px}p{max-width:900px;color:#b3bcb9}small{color:#a3bfb1}nav{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0}button{font:500 13px system-ui;padding:9px 14px;border:1px solid #3f4845;border-radius:6px;color:#cbd4cf;background:transparent;cursor:pointer}button[aria-pressed=true]{background:#c9d8ce;color:#14221c;border-color:#c9d8ce}article{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px 24px}figure{margin:0;min-width:0}figcaption{margin-bottom:10px;font-weight:500;color:#c5d0c9}img{display:block;width:100%;height:auto;border:1px solid #363c39;border-radius:5px}figure[hidden]{display:none}a{color:#b8d5c6}@media(max-width:850px){article{grid-template-columns:1fr}main{padding:26px 16px}}</style><main><header><small>APHEKA · 6.24.1 · 4 NOV 2026</small><h1>Interfaz y flujos revisados</h1><p>Capturas con datos aislados. Los diez apartados generales corresponden al frontend compilado; las conversaciones, fuentes, catálogo y transcripción usan respuestas controladas. No muestran tus materiales ni una cuenta real de IA.</p><p>'''+installer+''' La revisión incluye continuidad Gemini/OpenCode, confirmación después de acciones, buscador sin fondo, chat extendido, proyectos, fuentes por consulta, búsqueda interna de artistas, cola independiente y controles de tareas adaptables.</p>'''+download+'''</header><nav aria-label="Filtrar capturas"><button data-filter="all" aria-pressed="true">Todas</button><button data-filter="general" aria-pressed="false">Apartados</button><button data-filter="chat" aria-pressed="false">Charvis</button><button data-filter="music" aria-pressed="false">Música</button><button data-filter="tasks" aria-pressed="false">Tareas</button></nav><article>'''+''.join(figures)+'''</article></main><script>for(const button of document.querySelectorAll('[data-filter]'))button.onclick=()=>{for(const item of document.querySelectorAll('[data-filter]'))item.setAttribute('aria-pressed',String(item===button));for(const figure of document.querySelectorAll('figure'))figure.hidden=button.dataset.filter!=='all'&&button.dataset.filter!==figure.dataset.group;};</script></html>'''
(folder/'qa-624-gallery.html').write_text(html,encoding='utf-8');print(f'Galería: {len(figures)} capturas')
